    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    line = next(v for v, _ in counts.most_common() if v != background)

    # Propagate each sample color independently through connected line cells.
    # Equidistant fronts leave the original line color unchanged.
    colors = {v for row in grid for v in row
              if v != background and v != line}
    distances = {}
    for color in colors:
        dist = [[None] * w for _ in range(h)]
        q = deque()
        for r in range(h):
            for c in range(w):
                if grid[r][c] != line:
                    continue
                if any(0 <= r+dr < h and 0 <= c+dc < w and
                       grid[r+dr][c+dc] == color
                       for dr, dc in ((1,0),(-1,0),(0,1),(0,-1))):
                    dist[r][c] = 0
                    q.append((r, c))
        while q:
            r, c = q.popleft()
            for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nr, nc = r+dr, c+dc
                if (0 <= nr < h and 0 <= nc < w and
                        grid[nr][nc] == line and dist[nr][nc] is None):
                    dist[nr][nc] = dist[r][c] + 1
                    q.append((nr, nc))
        distances[color] = dist

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != line:
                continue
            candidates = [(d[r][c], color) for color, d in distances.items()
                          if d[r][c] is not None]
