def transform(grid):
    h, w = len(grid), len(grid[0])
    vals = {}
    for r in range(h):
        for c in range(w):
            vals.setdefault(grid[r][c], []).append((r, c))

    # The most common color is the canvas; the next most common is the
    # outlining color. Recolor outline cells according to the nearest
    # non-canvas, non-outline color sample.
    background = max(vals, key=lambda x: len(vals[x]))
    outline = max((x for x in vals if x != background),
                  key=lambda x: len(vals[x]))

    samples = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (background, outline)]
    out = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] != outline or not samples:
                continue
            best = min(abs(r-y) + abs(c-x) for y, x, _ in samples)
            winners = {color for y, x, color in samples
                       if abs(r-y) + abs(c-x) == best}
            if len(winners) == 1:
                out[r][c] = next(iter(winners))
    return out
